def transform(grid):
    g = np.array(grid)
    out = g.copy()
    for comp in components(g != 0):
        y0, x0, y1, x1 = bbox(comp)
        for (y, x) in comp:
            d = min(y - y0, y1 - y, x - x0, x1 - x)
            if d == 0:
                c = 1
            else:
                c = 2 if d % 2 == 1 else 3
            out[y, x] = c
        emit(out, f"Painted concentric rings in rectangle at rows {y0}-{y1}, cols {x0}-{x1}: border 1, then alternating 2/3 inward by depth.")
    emit(out, "All rectangles ringed; final output.")
    return out
